#include <iostream>
using namespace std;

int loop_1790() {
    int sum = 0;
    for (int i = 1; i <= 6; i++) {
        if (i == 4) continue;
        sum += i;
    }
    return sum;
}

int main() {
    cout << loop_1790() << endl;
    return 0;
}

