#include <iostream>
#include <vector>
using namespace std;
int stream_1793() {
    vector<int> items = {2, 4, 6};
    int total = 0;
    for (int x : items) total += x * 4;
    return total;
}
int main() {
    cout << stream_1793() << endl;
    return 0;
}

#include <iostream>
using namespace std;
int factorial_1794(int n) {
    if (n <= 1) return 1;
    return n * factorial_1794(n - 1);
}
int main() {
    cout << factorial_1794(3) << endl;
    return 0;
}

